using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using Mewgic;using Mewgic.Core;using Mewgic.Daily;
[InitializeOnLoad]public static class DailyActivitiesTests
{
 static string output;
 static readonly List<string> checks=new List<string>();static readonly Queue<Action> actions=new Queue<Action>();static double next;static bool had;static string original;
 static DailyActivitiesTests(){EditorApplication.update+=Tick;}
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks.Add(name);}static void Add(Action a)=>actions.Enqueue(a);static void Tap(string name)=>Add(()=>Click(name));
 static void Click(string name){Canvas.ForceUpdateCanvases();var g=GameObject.Find(name);Check(g!=null,"UI exists "+name);var r=(RectTransform)g.transform;var d=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(d,hits);Check(hits.Count>0&&hits[0].gameObject==g,"Real top raycast "+name);ExecuteEvents.Execute(g,d,ExecuteEvents.pointerClickHandler);}
 public static void Models()
 {
  var now=new DateTimeOffset(2026,10,25,10,0,0,TimeSpan.FromHours(3));var ledger=new ProgressLedger(new ProgressData(),_=>{},()=>now);Check(ledger.ObserveDaily()&&ledger.GiftReady,"New local day gift ready");Check(!ledger.ClaimDailyTask(DailyTaskKind.Wins),"Unfinished task cannot claim");Check(ledger.ClaimDailyGift()&&ledger.Remaining(BoosterKind.Hint)==4,"Gift awards one actual hint");for(int i=0;i<8;i++)Check(!ledger.ClaimDailyGift()&&ledger.Remaining(BoosterKind.Hint)==4,"Repeated gift blocked "+i);
  Check(!ledger.Claim(1,3,false,out _,"not-won",2)&&ledger.DailySnapshot.progress.All(x=>x==0),"Non victory cannot advance daily goals");
  Check(ledger.Claim(1,2,true,out _,"run-a",2)&&ledger.DailySnapshot.progress.SequenceEqual(new[]{2,1,2,0}),"Real victory event increments bottles wins and stars");Check(ledger.Claim(1,2,true,out _,"run-a",2)&&ledger.DailySnapshot.progress.SequenceEqual(new[]{2,1,2,0}),"Same victory receipt counted once");
  var reloaded=new ProgressLedger(JsonUtility.FromJson<ProgressData>(JsonUtility.ToJson(ledger.Snapshot)),_=>{},()=>now);Check(reloaded.Claim(1,2,true,out _,"run-a",2)&&reloaded.DailySnapshot.progress[1]==1,"Receipt deduplication survives reload");
  Check(ledger.Claim(1,3,true,out _,"run-b",2)&&ledger.DailySnapshot.progress.SequenceEqual(new[]{4,2,5,0}),"New replay counts as new real run");Check(ledger.Claim(2,3,true,out _,"run-c",3)&&ledger.DailySnapshot.progress[2]==6,"Progress is capped at goal");
  var p=PrototypeApp.LoadLevel();var booster=new BoosterActions(p,ledger,p.Count);Check(!booster.Undo()&&ledger.DailySnapshot.progress[3]==0,"Invalid booster action does not count");Check(booster.Hint(out _)&&ledger.DailySnapshot.progress[3]==1,"Successful spend counts booster use");
  foreach(DailyTaskKind kind in Enum.GetValues(typeof(DailyTaskKind))){var reward=DailyRules.Reward(kind);int before=ledger.Remaining(reward);Check(ledger.ClaimDailyTask(kind)&&ledger.Remaining(reward)==before+1,"Claim completed task "+kind);for(int i=0;i<3;i++)Check(!ledger.ClaimDailyTask(kind)&&ledger.Remaining(reward)==before+1,"Task duplicate blocked "+kind+i);}
  now=now.AddHours(19);Check(!ledger.ClaimDailyGift(),"New calendar day alone is insufficient before twenty hours");now=now.AddHours(1);Check(ledger.ObserveDaily()&&ledger.DailySnapshot.progress.All(x=>x==0)&&ledger.DailySnapshot.claimed.All(x=>!x),"Local midnight resets only tasks, not lifetime progress");Check(ledger.Completed(1)&&ledger.BestStars(1)==3&&ledger.ClaimDailyGift(),"Next day gift after twenty hours preserves existing stars");
  var high=now;now=now.AddHours(-2);Check(ledger.DailyClockBlocked&&!ledger.ObserveDaily()&&!ledger.ClaimDailyGift()&&!ledger.ClaimDailyTask(DailyTaskKind.Wins),"Clock rollback blocks daily operations");int oldBoost=ledger.DailySnapshot.progress[3];Check(ledger.TrySpend(BoosterKind.Undo)&&ledger.DailySnapshot.progress[3]==oldBoost,"Ordinary gameplay remains usable during daily clock quarantine");now=high;Check(ledger.ObserveDaily()&&!ledger.DailyClockBlocked,"Clock recovers at high water mark");
  now=now.ToOffset(TimeSpan.FromHours(-12));Check(ledger.DailyClockBlocked&&!ledger.ClaimDailyGift(),"Timezone changing local date backwards cannot farm");now=high.AddDays(4);int oldHint=ledger.Remaining(BoosterKind.Hint);Check(ledger.ObserveDaily()&&ledger.ClaimDailyGift()&&ledger.Remaining(BoosterKind.Hint)==oldHint+1,"Skipped days grant only one gift, no accumulated rewards");
  var legacy=JsonUtility.FromJson<ProgressData>("{\"version\":1,\"undo\":2,\"hint\":7,\"extra\":1,\"shuffle\":1,\"levels\":[{\"level\":1,\"bestStars\":2,\"rewardClaimed\":true}],\"claimedMilestones\":[\"map.village.v1\"]}");var migrated=new ProgressLedger(legacy,_=>{},()=>now);Check(migrated.ObserveDaily()&&migrated.BestStars(1)==2&&migrated.Remaining(BoosterKind.Hint)==7&&migrated.MilestoneClaimed("map.village.v1"),"Legacy save migrates with balances stars and chests intact");
  var failed=new ProgressLedger(new ProgressData(),_=>throw new IOException("test failure"),()=>now);Check(!failed.ClaimDailyGift()&&failed.Remaining(BoosterKind.Hint)==3&&failed.DailySnapshot.lastGiftDay==0,"Gift save failure is atomic");Check(!failed.TrySpend(BoosterKind.Hint)&&failed.DailySnapshot.progress[3]==0,"Failed booster save cannot progress task");
  var complete=ledger.Snapshot;complete.daily.lastGiftDay=0;complete.daily.lastGiftUtc=0;complete.daily.claimed=new bool[4];complete.daily.progress=new[]{4,2,6,1};var failTask=new ProgressLedger(complete,_=>throw new IOException("test failure"),()=>now);int beforeTask=failTask.Remaining(BoosterKind.ExtraBottle);Check(!failTask.ClaimDailyTask(DailyTaskKind.Stars)&&!failTask.DailySnapshot.claimed[2]&&failTask.Remaining(BoosterKind.ExtraBottle)==beforeTask,"Task reward save failure is atomic");
  var full=new ProgressLedger(new ProgressData{hint=int.MaxValue},_=>{},()=>now);Check(!full.ClaimDailyGift()&&full.DailySnapshot.lastGiftDay==0,"Gift integer overflow cannot set claimed flag");Check(!ledger.ClaimDailyTask((DailyTaskKind)99),"Unknown task rejected");
  string key="Mewgic.Tests.Part07A."+Guid.NewGuid().ToString("N");try{var disk=GameplayProgress.Open(key,()=>now);Check(disk.LocalNow==now,"Persisted ledger uses injected local clock");disk.ObserveDaily();Check(disk.ClaimDailyGift(),"Real disk gift save");disk.Claim(1,3,true,out _,"disk-a",2);disk.Claim(1,3,true,out _,"disk-b",2);Check(disk.ClaimDailyTask(DailyTaskKind.Wins),"Real disk task claim");var again=GameplayProgress.Open(key,()=>now);Check(!again.ClaimDailyGift()&&!again.ClaimDailyTask(DailyTaskKind.Wins)&&again.DailySnapshot.progress[1]==2&&again.DailySnapshot.claimed[1],"Closing/reopening persisted ledger preserves counts and claim markers");}finally{PlayerPrefs.DeleteKey(key);PlayerPrefs.Save();}
 }
 static Puzzle Model()=>(Puzzle)typeof(PrototypeApp).GetField("puzzle",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(UnityEngine.Object.FindFirstObjectByType<PrototypeApp>());
 public static void Run()
 {output=BetaCapturePaths.NewRun("DailyActivitiesTests");
  if(EditorApplication.isPlaying)throw new Exception("Stop Play first");checks.Clear();actions.Clear();Models();had=PlayerPrefs.HasKey(GameplayProgress.StorageKey);original=PlayerPrefs.GetString(GameplayProgress.StorageKey,"");GameplayProgress.UseTestProfile();GameplayLevelCatalog.ResetSelection();
  Tap("MissionsButton");Add(()=>{Check(UnityEngine.Object.FindFirstObjectByType<DailyActivitiesPanel>().IsOpen,"Home missions opens actual screen");Capture(900,1600);Capture(900,1950);Capture(900,2000);Capture(900,2000,true);Capture(360,640);});Add(()=>ScreenCapture.CaptureScreenshot(output+"PART07A_TASKS_GAMEVIEW.png"));Tap("DailyGiftTab");Add(()=>{Capture(900,2000,true,"_GIFT");Capture(360,640,false,"_GIFT");});Tap("ClaimDailyGift");Add(()=>Check(GameplayProgress.Current.Remaining(BoosterKind.Hint)==4&&!GameObject.Find("ClaimDailyGift").GetComponent<Button>().interactable,"Real gift UI claims once"));Tap("DailyClose");Tap("DailyGiftButton");Add(()=>{Check(UnityEngine.Object.FindFirstObjectByType<DailyActivitiesPanel>().GiftVisible&&!GameObject.Find("ClaimDailyGift").GetComponent<Button>().interactable,"Reopening gift cannot claim again");ScreenCapture.CaptureScreenshot(output+"PART07A_GIFT_GAMEVIEW.png");});Tap("DailyTasksTab");Tap("DailyAction_3");
  Add(()=>Check(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="Gameplay","Go enters existing gameplay"));Tap("Hint");Add(()=>Check(GameplayProgress.Current.DailySnapshot.progress[3]==1,"Actual gameplay hint counts daily booster"));Tap("Bottle 1");
  foreach(var move in PuzzleSolver.Solve(GameplayLevelCatalog.Load(1).Bottles).Moves){int a=move.Source,b=move.Target;Tap("Bottle "+(a+1));Tap("Bottle "+(b+1));}
  Add(()=>Check(Model().Won&&GameplayProgress.Current.DailySnapshot.progress.SequenceEqual(new[]{2,1,3,1}),"Real first win updates all earned tasks exactly once"));Tap("ResultHome");Tap("MissionsButton");Add(()=>Check(GameObject.Find("DailyTask_3/ProgressTrack/ProgressValue").GetComponent<TMPro.TMP_Text>().text=="1/1","Mission UI reflects real booster event"));Tap("DailyAction_3");Add(()=>Check(GameplayProgress.Current.Remaining(BoosterKind.Shuffle)==2&&GameplayProgress.Current.DailySnapshot.claimed[3],"Task UI claim adds real shuffle charge"));Tap("DailyClose");Tap("Play");
  foreach(var move in PuzzleSolver.Solve(GameplayLevelCatalog.Load(1).Bottles).Moves){int a=move.Source,b=move.Target;Tap("Bottle "+(a+1));Tap("Bottle "+(b+1));}
  Tap("ResultHome");Tap("MissionsButton");Add(()=>{Check(GameplayProgress.Current.DailySnapshot.progress.SequenceEqual(new[]{4,2,6,1}),"Actual second run completes all daily goals");ScreenCapture.CaptureScreenshot(output+"PART07A_READY_GAMEVIEW.png");});Tap("DailyAction_0");Tap("DailyAction_1");Tap("DailyAction_2");Add(()=>Check(GameplayProgress.Current.DailySnapshot.claimed.All(x=>x),"All task rewards claimed once"));Add(()=>ScreenCapture.CaptureScreenshot(output+"PART07A_CLAIMED_GAMEVIEW.png"));Tap("DailyClose");Tap("NavMap");Add(()=>Check(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="LevelMap","Existing Home Map preserved"));Tap("MapHome");
  SessionState.SetBool("DailyActivitiesTest",true);EditorSceneManager.OpenScene("Assets/Scenes/Home.unity");EditorApplication.isPlaying=true;next=EditorApplication.timeSinceStartup+2;
 }
 static Rect Bounds(RectTransform r,RectTransform relative){var corners=new Vector3[4];r.GetWorldCorners(corners);Vector2 min=Vector2.one*float.MaxValue,max=-min;foreach(var p in corners){var v=(Vector2)relative.InverseTransformPoint(p);min=Vector2.Min(min,v);max=Vector2.Max(max,v);}return Rect.MinMaxRect(min.x,min.y,max.x,max.y);}
 public static void Capture(int width,int height,bool inset=false,string suffix="")
 {
  var ui=UnityEngine.Object.FindFirstObjectByType<DailyActivitiesPanel>();var root=(RectTransform)GameObject.Find("DailyActivitiesScreen").transform;var safe=(RectTransform)root.parent;var canvas=safe.GetComponentInParent<Canvas>();var cam=Camera.main;var min=safe.anchorMin;var max=safe.anchorMax;var mode=canvas.renderMode;var camera=canvas.worldCamera;var plane=canvas.planeDistance;var old=RenderTexture.active;var target=cam.targetTexture;var rt=new RenderTexture(width,height,24);Texture2D tex=null;
  try{canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=1;cam.targetTexture=rt;if(inset){safe.anchorMin=new Vector2(.04f,.05f);safe.anchorMax=new Vector2(.96f,.96f);}Canvas.ForceUpdateCanvases();ui.Layout();Canvas.ForceUpdateCanvases();foreach(var b in root.GetComponentsInChildren<Button>()){var r=(RectTransform)b.transform;var rect=Bounds(r,safe);Check(safe.rect.Contains(rect.min)&&safe.rect.Contains(rect.max),"Daily button inside safe "+b.name+height);var pad=b.GetComponent<Image>().raycastPadding;Check((r.rect.height-pad.y-pad.w)*canvas.scaleFactor>=43.9f&&(r.rect.width-pad.x-pad.z)*canvas.scaleFactor>=43.9f,"44 pixel daily touch target "+b.name+width);}cam.Render();RenderTexture.active=rt;tex=new Texture2D(width,height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();File.WriteAllBytes(output+"PART07A_LAYOUT_"+width+"x"+height+(inset?"_SAFE":"")+suffix+".png",tex.EncodeToPNG());}
  finally{cam.targetTexture=target;RenderTexture.active=old;canvas.renderMode=mode;canvas.worldCamera=camera;canvas.planeDistance=plane;safe.anchorMin=min;safe.anchorMax=max;if(tex!=null)UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);Canvas.ForceUpdateCanvases();ui.Layout();}
 }
 [Serializable]class Result{public string screenshots;public bool success;public string error;public int count;public string[] checks;}
 static void Finish(string error){SessionState.SetBool("DailyActivitiesTest",false);if(PlayerPrefs.HasKey(GameplayProgress.StorageKey)!=had||PlayerPrefs.GetString(GameplayProgress.StorageKey,"")!=original)error=(error??"")+" Player save changed";else checks.Add("Real player storage unchanged");File.WriteAllText("docs/PART07A_TEST_RESULTS.json",JsonUtility.ToJson(new Result{screenshots=output,success=error==null,error=error,count=checks.Count,checks=checks.ToArray()},true));EditorApplication.isPlaying=false;GameplayProgress.RestorePlayerProfile();GameplayLevelCatalog.ResetSelection();}
 static void Tick(){if(!SessionState.GetBool("DailyActivitiesTest",false)||!EditorApplication.isPlaying||EditorApplication.timeSinceStartup<next)return;try{next=EditorApplication.timeSinceStartup+1.15;if(actions.Count==0){Finish(null);return;}actions.Dequeue()();}catch(Exception e){Finish(e.ToString());}}
}
